CREATE TYPE public.app_role AS ENUM ('admin', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated, service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id = auth.uid());
CREATE FUNCTION public.default_agency_settings() RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT '{"exchangeRate":1476.07,"margin":0.6,"paymentFixedRwf":0,"paymentRate":0,"infrastructureRwf":0,"productionRwf":0,"allowanceRwf":0,"models":{"ugc":{"name":"MiniMax H3","resolution":"768p","endpoint":"","cost10":1.04,"cost15":1.54,"sound10":1.04,"sound15":1.54},"product":{"name":"Kling 3.0 Standard","resolution":"Endpoint-defined","endpoint":"","cost10":0.84,"cost15":1.26,"sound10":1.26,"sound15":1.89},"cinematic":{"name":"Seedance 2.0","resolution":"720p","endpoint":"","cost10":2.4,"cost15":3.6,"sound10":2.4,"sound15":3.6}},"overrides":{},"contacts":{"phone":"","whatsapp":"","email":"","instagram":""}}'::jsonb $$;
CREATE TABLE public.agency_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), config jsonb NOT NULL DEFAULT public.default_agency_settings(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.agency_settings TO authenticated; GRANT ALL ON public.agency_settings TO service_role;
ALTER TABLE public.agency_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_settings ON public.agency_settings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.calculate_video_quote(ad_type text, seconds integer, sound boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE c jsonb; m jsonb; provider numeric; base numeric; amount numeric; margin numeric; rate numeric; manual numeric; k text;
BEGIN
IF ad_type NOT IN ('ugc','product','cinematic') OR seconds NOT IN (10,15) THEN RAISE EXCEPTION 'Only 10s and 15s are self-service. Longer ads require Talk to a Pro.'; END IF;
SELECT config INTO c FROM public.agency_settings WHERE id=true; c:=coalesce(c,public.default_agency_settings()); m:=c->'models'->ad_type;
k:=CASE WHEN ad_type='product' AND sound THEN 'sound' ELSE 'cost' END || seconds::text;
provider:=(m->>k)::numeric; margin:=(c->>'margin')::numeric; rate:=(c->>'paymentRate')::numeric;
IF margin<0 OR margin>=1 OR rate<0 OR margin+rate>=1 OR provider<0 OR (c->>'exchangeRate')::numeric<=0 THEN RAISE EXCEPTION 'Invalid pricing configuration'; END IF;
base:=provider*(c->>'exchangeRate')::numeric+(c->>'paymentFixedRwf')::numeric+(c->>'infrastructureRwf')::numeric+(c->>'productionRwf')::numeric+(c->>'allowanceRwf')::numeric;
amount:=ceil(base/(1-margin-rate)/100)*100;
k:=ad_type||':'||seconds::text||':'||CASE WHEN ad_type='product' AND sound THEN 'sound' ELSE 'silent' END;
manual:=(c->'overrides'->>k)::numeric; IF manual IS NOT NULL THEN IF manual<amount THEN RAISE EXCEPTION 'Manual price is below the target gross margin'; END IF; amount:=ceil(manual/100)*100; END IF;
RETURN jsonb_build_object('adType',ad_type,'duration',seconds,'sound',sound,'total',amount,'currency','RWF','providerCostUsd',provider,'exchangeRate',c->'exchangeRate','margin',margin,'paymentCostRwf',(c->>'paymentFixedRwf')::numeric+amount*rate,'infrastructureRwf',c->'infrastructureRwf','productionRwf',c->'productionRwf','allowanceRwf',c->'allowanceRwf','allInCostRwf',base+amount*rate,'model',m->>'name','endpoint',m->>'endpoint','resolution',m->>'resolution'); END $$;
REVOKE ALL ON FUNCTION public.calculate_video_quote(text,integer,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.calculate_video_quote(text,integer,boolean) TO service_role;
CREATE FUNCTION public.video_price(ad_type text, seconds integer, sound boolean DEFAULT false) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.calculate_video_quote(ad_type,seconds,sound)-ARRAY['providerCostUsd','exchangeRate','margin','paymentCostRwf','infrastructureRwf','productionRwf','allowanceRwf','allInCostRwf','model','endpoint','resolution'] $$;
REVOKE ALL ON FUNCTION public.video_price(text,integer,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.video_price(text,integer,boolean) TO anon,authenticated,service_role;
CREATE FUNCTION public.agency_contacts() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT config->'contacts' FROM public.agency_settings WHERE id=true),public.default_agency_settings()->'contacts') $$;
REVOKE ALL ON FUNCTION public.agency_contacts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.agency_contacts() TO anon,authenticated,service_role;
CREATE TABLE public.video_quotes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, ad_type text NOT NULL, duration integer NOT NULL CHECK(duration IN (10,15)), sound boolean NOT NULL, total_rwf numeric NOT NULL, cost_snapshot jsonb NOT NULL, campaign jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now()+interval '30 minutes'));
GRANT SELECT ON public.video_quotes TO authenticated; GRANT ALL ON public.video_quotes TO service_role;
ALTER TABLE public.video_quotes ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_quotes ON public.video_quotes FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.reserve_video_quote(ad_type text, seconds integer, sound boolean, campaign jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q jsonb; r public.video_quotes; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; q:=public.calculate_video_quote(ad_type,seconds,sound); INSERT INTO public.video_quotes(user_id,ad_type,duration,sound,total_rwf,cost_snapshot,campaign) VALUES(auth.uid(),ad_type,seconds,sound,(q->>'total')::numeric,q,campaign) RETURNING * INTO r; RETURN jsonb_build_object('id',r.id,'total',r.total_rwf,'expiresAt',r.expires_at,'status','quoted','generationAvailable',false); END $$;
REVOKE ALL ON FUNCTION public.reserve_video_quote(text,integer,boolean,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_video_quote(text,integer,boolean,jsonb) TO authenticated;
CREATE TABLE public.video_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, quote_id uuid NOT NULL UNIQUE REFERENCES public.video_quotes(id), ad_type text NOT NULL, duration integer NOT NULL CHECK(duration IN (10,15)), model text NOT NULL, endpoint text NOT NULL, resolution text NOT NULL, sound boolean NOT NULL, cost_snapshot jsonb NOT NULL, quoted_rwf numeric NOT NULL, charged_rwf numeric NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'blocked' CHECK(status IN ('blocked','queued','processing','succeeded','failed','cancelled')), output_path text, provider_reference text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.video_jobs TO authenticated; GRANT ALL ON public.video_jobs TO service_role;
ALTER TABLE public.video_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_jobs ON public.video_jobs FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.professional_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text NOT NULL UNIQUE DEFAULT ('AMA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), user_id uuid NOT NULL DEFAULT auth.uid(), customer_name text NOT NULL, ad_type text NOT NULL CHECK(ad_type IN ('ugc','product','cinematic','flyer','banner','other')), duration integer NOT NULL CHECK(duration IN (10,15,30,60)), contact_method text NOT NULL CHECK(contact_method IN ('phone','whatsapp','email','instagram')), contact_detail text NOT NULL, answers jsonb NOT NULL, campaign jsonb NOT NULL DEFAULT '{}', related_job_id uuid REFERENCES public.video_jobs(id), assets jsonb NOT NULL DEFAULT '[]', creative_brief text NOT NULL, status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','awaiting_contact','contacted','in_consultation','quoted','in_production','completed','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.professional_requests TO authenticated; GRANT UPDATE(status,updated_at) ON public.professional_requests TO authenticated; GRANT ALL ON public.professional_requests TO service_role;
ALTER TABLE public.professional_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_request_insert ON public.professional_requests FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='new');
CREATE POLICY read_requests ON public.professional_requests FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY update_requests ON public.professional_requests FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.professional_request_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.professional_requests(id), author_id uuid NOT NULL DEFAULT auth.uid(), body text NOT NULL, assignee text, quoted_rwf numeric CHECK(quoted_rwf>=0), contacted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.professional_request_notes TO authenticated; GRANT ALL ON public.professional_request_notes TO service_role;
ALTER TABLE public.professional_request_notes ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_notes ON public.professional_request_notes FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin') AND author_id=auth.uid());
CREATE TABLE public.professional_request_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.professional_requests(id), status text NOT NULL, changed_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.professional_request_status_history TO authenticated; GRANT ALL ON public.professional_request_status_history TO service_role;
ALTER TABLE public.professional_request_status_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_history ON public.professional_request_status_history FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.track_pro_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.professional_request_status_history(request_id,status,changed_by) VALUES(NEW.id,NEW.status,auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER pro_status AFTER INSERT OR UPDATE ON public.professional_requests FOR EACH ROW EXECUTE FUNCTION public.track_pro_status();
CREATE INDEX pro_requests_user ON public.professional_requests(user_id,created_at DESC); CREATE INDEX pro_requests_status ON public.professional_requests(status,created_at DESC);